pub fn is_size_preserving_method(method_name: String) -> bool {
    ((((((((method_name.clone().as_str() == "map".to_string().as_str()) || (method_name.clone().as_str() == "filter".to_string().as_str())) || (method_name.clone().as_str() == "flat_map".to_string().as_str())) || (method_name.clone().as_str() == "skip".to_string().as_str())) || (method_name.clone().as_str() == "enumerate".to_string().as_str())) || (method_name.clone().as_str() == "sort_by".to_string().as_str())) || (method_name.clone().as_str() == "concat".to_string().as_str())) || (method_name.clone().as_str() == "reverse".to_string().as_str()))
}

pub fn method_preserves_collection_size(method_semantics: Option<Rc<MethodSemantics>>) -> bool {
    if (method_semantics.clone() == None) {
        false
} else {
        match (*method_semantics.clone().unwrap()).clone() {
    MethodSemantics::AlgebraMethodSemantics { method_def: method_def, .. } => is_size_preserving_method(method_def.name.clone()),
    _ => false,
}
}
}

pub fn receiver_size_var(mut recv: Rc<Node>) -> Rc<SizeExpr> {
    loop {
        match (*recv.expr_data.clone()).clone() {
    ExprData::ExprVar { .. } => { break Rc::new(SizeExpr::SizeLen {
    collection: expr_var_name(recv.clone()),
}); },
    ExprData::ExprFieldAccess { .. } => { break Rc::new(SizeExpr::SizeLen {
    collection: field_access_field(recv.clone()),
}); },
    ExprData::ExprMethodCall { method_semantics: method_semantics, .. } => { let inner_recv = match recv.children.clone().first().cloned() {
    Some(r) => r.clone(),
    None => recv.clone(),
};
if method_preserves_collection_size(method_semantics.clone()) {
            {
                let __tco_0 = inner_recv.clone();
recv = __tco_0;
continue;
}
} else {
            break Rc::new(SizeExpr::SizeLen {
    collection: "__expr".to_string(),
});
} },
    _ => { break Rc::new(SizeExpr::SizeLen {
    collection: "__expr".to_string(),
}); },
}
}
}

pub fn size_binder_name(size: Rc<SizeExpr>) -> String {
    match (*size).clone() {
    SizeExpr::SizeLen { collection: c, .. } => v2_rt::concat("_".to_string(), c.clone()),
    SizeExpr::SizeVar { name: n, .. } => n.clone(),
    _ => "_i".to_string(),
}
}

pub fn resolve_lambda_arg(mc_arg_nodes: Rc<Vec<Rc<Node>>>) -> Option<Rc<Node>> {
    {
        let f_arg = Rc::new({ let mut __result = Vec::new(); for a in mc_arg_nodes.clone().iter().cloned() { if (a.name.clone().as_str() == "f".to_string().as_str()) { __result.push(a); } } __result }).first().cloned();
match f_arg {
    Some(fa) => Some(arg_value(fa.clone())),
    None => Rc::new({ let mut __result = Vec::new(); for a in mc_arg_nodes.clone().iter().cloned() { __result.push(arg_value(a.clone())); } __result }).first().cloned(),
}
}
}

pub fn resolve_callback_cost(lambda_arg: Option<Rc<Node>>, recv_r: Rc<SummaryResult>, func_index: Rc<HashMap<String, Rc<FuncEntry>>>, scc_index: Rc<HashMap<String, Rc<SccInfo>>>, parser_always_advancing: Rc<HashMap<String, bool>>, recursion_ctx: RecursionContext) -> Rc<SummaryResult> {
    match lambda_arg {
    Some(la) => match (*la.expr_data.clone()).clone() {
    ExprData::ExprVar { .. } => {
        let fn_ref = expr_var_name(la.clone());
match v2_rt::map_get(&func_index, fn_ref.clone()) {
    Some(_) => get_or_compute_summary(fn_ref.clone(), func_index.clone(), scc_index, recv_r.table.clone(), parser_always_advancing, recursion_ctx),
    None => cost_of_expr(la.clone(), func_index.clone(), scc_index, recv_r.table.clone(), parser_always_advancing, recursion_ctx),
}
},
    _ => cost_of_expr(la.clone(), func_index.clone(), scc_index, recv_r.table.clone(), parser_always_advancing, recursion_ctx),
},
    None => Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    output_size: v2_rt::rc_empty_map::<Rc<CostExpr>>(),
    certainty: Certainty::Conservative,
}),
    table: recv_r.table.clone(),
}),
}
}

pub fn cost_of_method_by_shape(shape: Rc<CostShape>, recv_r: Rc<SummaryResult>, mc_args: Rc<Vec<Rc<Node>>>, size: Rc<SizeExpr>, binder: String, func_index: Rc<HashMap<String, Rc<FuncEntry>>>, scc_index: Rc<HashMap<String, Rc<SccInfo>>>, parser_always_advancing: Rc<HashMap<String, bool>>, recursion_ctx: RecursionContext) -> Rc<SummaryResult> {
    match (*shape).clone() {
    CostShape::ShapeIterateBody { produces_collection: pc, .. } => {
        let lambda_arg = resolve_lambda_arg(mc_args);
let body_result = resolve_callback_cost(lambda_arg, recv_r.clone(), func_index, scc_index, parser_always_advancing, recursion_ctx);
let loop_work = cost_loop(binder.clone(), size.clone(), body_result.summary.clone().work.clone());
let os = if (pc.clone() == false) {
            body_result.summary.clone().output_size.clone()
} else {
            {
                let r = v2_rt::rc_map_insert(Rc::new(HashMap::new()) /* BRIDGE: empty_map value type unresolved */, "result".to_string(), cost_loop(binder.clone(), size.clone(), Rc::new(CostExpr::CostConst {
    value: 1,
})));
r
}
};
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(recv_r.summary.clone().work.clone(), loop_work.clone()),
    span: cost_seq(recv_r.summary.clone().span.clone(), loop_work.clone()),
    output_size: os,
    certainty: body_result.summary.clone().certainty.clone(),
}),
    table: body_result.table.clone(),
})
},
    CostShape::ShapeSortBody => {
        let lambda_arg = resolve_lambda_arg(mc_args);
let key_result = match lambda_arg {
    Some(la) => cost_of_expr(la.clone(), func_index, scc_index, recv_r.table.clone(), parser_always_advancing, recursion_ctx),
    None => Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    span: Rc::new(CostExpr::CostConst {
    value: 1,
}),
    output_size: v2_rt::rc_empty_map::<Rc<CostExpr>>(),
    certainty: Certainty::Proven,
}),
    table: recv_r.table.clone(),
}),
};
let log_factor = Rc::new(CostExpr::CostLog {
    base: 2,
    argument: size.clone(),
});
let per_comparison = key_result.summary.clone().work.clone();
let sort_work = Rc::new(CostExpr::CostMul {
    left: cost_loop(binder.clone(), size.clone(), per_comparison),
    right: log_factor,
});
let sort_os = v2_rt::rc_map_insert(Rc::new(HashMap::new()) /* BRIDGE: empty_map value type unresolved */, "result".to_string(), cost_loop(binder.clone(), size.clone(), Rc::new(CostExpr::CostConst {
    value: 1,
})));
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(recv_r.summary.clone().work.clone(), sort_work.clone()),
    span: cost_seq(recv_r.summary.clone().span.clone(), sort_work.clone()),
    output_size: sort_os,
    certainty: key_result.summary.clone().certainty.clone(),
}),
    table: key_result.table.clone(),
})
},
    CostShape::ShapeLinearScan { produces_collection: pc, .. } => {
        let loop_work = cost_loop(binder.clone(), size.clone(), Rc::new(CostExpr::CostConst {
    value: 1,
}));
let scan_os = if pc.clone() {
            {
                let r = v2_rt::rc_map_insert(Rc::new(HashMap::new()) /* BRIDGE: empty_map value type unresolved */, "result".to_string(), cost_loop(binder.clone(), size.clone(), Rc::new(CostExpr::CostConst {
    value: 1,
})));
r
}
} else {
            {
                let r = Rc::new(HashMap::new()) /* BRIDGE: empty_map value type unresolved */;
r
}
};
Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(recv_r.summary.clone().work.clone(), loop_work.clone()),
    span: cost_seq(recv_r.summary.clone().span.clone(), loop_work.clone()),
    output_size: scan_os,
    certainty: recv_r.summary.clone().certainty.clone(),
}),
    table: recv_r.table.clone(),
})
},
    CostShape::ShapeConstant => Rc::new(SummaryResult {
    summary: Rc::new(ComplexitySummary {
    work: cost_seq(recv_r.summary.clone().work.clone(), Rc::new(CostExpr::CostConst {
    value: 1,
})),
    span: cost_seq(recv_r.summary.clone().span.clone(), Rc::new(CostExpr::CostConst {
    value: 1,
})),
    output_size: v2_rt::rc_empty_map::<Rc<CostExpr>>(),
    certainty: recv_r.summary.clone().certainty.clone(),
}),
    table: recv_r.table.clone(),
}),
}
}

